import{c as a,S as t,j as e,m as o}from"./chunks/framework.VsSDrsS3.js";const c=JSON.parse('{"title":"架构思想 & 编程感悟","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/architecture/programming-philosophy.md","filePath":"knowledge/architecture/programming-philosophy.md","lastUpdated":1780046787000}'),l={name:"knowledge/architecture/programming-philosophy.md"};function i(n,r,s,p,g,h){return t(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="架构思想-编程感悟" tabindex="-1">架构思想 &amp; 编程感悟 <a class="header-anchor" href="#架构思想-编程感悟" aria-label="Permalink to “架构思想 &amp; 编程感悟”">​</a></h1><blockquote><p>以下内容汇总了多篇优秀技术博客的核心观点，并附上笔者在实践中的体会和补充。</p></blockquote><h2 id="计算机领域三个重要思想" tabindex="-1">计算机领域三个重要思想 <a class="header-anchor" href="#计算机领域三个重要思想" aria-label="Permalink to “计算机领域三个重要思想”">​</a></h2><p><strong>来源：</strong> <a href="https://ray-eldath.me/programming/three-important-ideas/" target="_blank" rel="noreferrer">Ray Eldath&#39;s Blog</a></p><p><strong>核心观点：</strong></p><ol><li><p><strong>抽象（Abstraction）：</strong> 隐藏底层复杂性，提供简洁接口。编程语言的演进（机器码→汇编→高级语言→框架）就是一层层抽象叠加的过程。好抽象的代价是&quot;泄漏&quot;——当底层出错时，你需要理解下面那层才能排查。</p></li><li><p><strong>分层（Layering）：</strong> OSI 七层模型、TCP/IP 协议栈、前端三层（结构/表现/行为）都是分层的体现。每层只关心与相邻层的接口，不关心其他层的实现。</p></li><li><p><strong>高阶（Higher-order）：</strong> 函数可以作为参数传递、作为返回值返回——这让代码复用上升到逻辑层面而非仅仅数据层面。React 的 HOC、Express 的中间件都是高阶思想的体现。</p></li></ol><h2 id="软件工程的最大难题" tabindex="-1">软件工程的最大难题 <a class="header-anchor" href="#软件工程的最大难题" aria-label="Permalink to “软件工程的最大难题”">​</a></h2><p><strong>来源：</strong> 阮一峰 — <em>软件工程的最大难题</em></p><p><strong>核心观点：</strong> 软件开发的真正困难不在于写出能运行的代码，而在于<strong>管理复杂性</strong>。随着功能增长，代码之间的交互呈指数级增长。没有银弹可以解决这个问题——模块化、微服务、DDD 都只是缓解手段。</p><p>关键推论：<strong>保持简单是保持软件可维护的唯一方法。</strong></p><h2 id="我在-20-年软件工程师生涯中学到的事情" tabindex="-1">我在 20 年软件工程师生涯中学到的事情 <a class="header-anchor" href="#我在-20-年软件工程师生涯中学到的事情" aria-label="Permalink to “我在 20 年软件工程师生涯中学到的事情”">​</a></h2><p><strong>总结要点：</strong></p><ul><li>代码是写给人看的，顺便能在机器上运行</li><li>可读性 &gt; 聪明 &gt; 性能（除非性能真成了瓶颈）</li><li>简单的东西能工作，复杂的东西可能也能工作，但出了问题你修不了复杂的东西</li><li>不要过度设计——为当前需求写代码，不要为&quot;可能的需求&quot;写代码</li><li>测试不是可选项，是对自己未来的善意</li><li>技术债就像信用卡，短期爽长期疼</li></ul><h2 id="编程十年的感悟" tabindex="-1">编程十年的感悟 <a class="header-anchor" href="#编程十年的感悟" aria-label="Permalink to “编程十年的感悟”">​</a></h2><p><strong>来源：</strong> 自由庄园</p><p><strong>要点：</strong></p><ul><li>技术是手段不是目的，解决实际问题比用&quot;正确&quot;的技术重要</li><li>保持好奇心，但不要追逐每一个新框架</li><li>基础设施（数据库、网络、操作系统）的积累比框架经验更有长期价值</li><li>写作是最好的思考工具——能把一件事写清楚，才说明你真正理解了</li></ul><h2 id="如何用低成本技术栈运营-mrr-公司" tabindex="-1">如何用低成本技术栈运营 MRR 公司 <a class="header-anchor" href="#如何用低成本技术栈运营-mrr-公司" aria-label="Permalink to “如何用低成本技术栈运营 MRR 公司”">​</a></h2><p><strong>来源：</strong> Steve Hanov&#39;s Blog</p><p><strong>核心技巧：</strong></p><ul><li>单台 $20/月 VPS 可支撑多个 SaaS 产品</li><li>SQLite 代替 PostgreSQL 用于中小规模应用</li><li>静态文件 + CDN 几乎零成本</li><li>关键不是技术栈多牛，而是<strong>产品能解决什么问题</strong></li></ul><h2 id="笔者的体会" tabindex="-1">笔者的体会 <a class="header-anchor" href="#笔者的体会" aria-label="Permalink to “笔者的体会”">​</a></h2><p>以上几篇文章的共同指向：<strong>保持简单、理解本质、持续学习</strong>。抽象是为了隐藏复杂性而不是增加复杂性；分层是为了解耦而不是制造壁垒；经验教训的核心不是记住&quot;结论&quot;而是理解当时的&quot;约束条件&quot;。技术会过时，但这些底层思维是长期有效的。</p>',23)])])}const m=a(l,[["render",i]]);export{c as __pageData,m as default};
